INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000209',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the German education system at B2","Use Bildungssystem vocabulary","Talk about education policy"],"explanation":{"intro":"Education system vocabulary covers the German school system, educational federalism, and PISA debate at B2.","culturalNote":"German Bildungssystem: federally organised (16 Kultusministerien). Key features: Dreigliedriges Schulsystem (three-tier — Hauptschule, Realschule, Gymnasium), PISA shock (2001 — Germany ranked poorly, triggered reforms), G8 vs G9 debate (Abitur in 8 vs 9 years), Gesamtschule (comprehensive school). Bildungsföderalismus (educational federalism) means 16 different systems. Key reforms: Ganztagsschule (all-day schools), inklusive Bildung."},"examples":[{"german":"Das gegliederte Schulsystem sortiert Kinder relativ früh nach vermeintlicher Leistungsfähigkeit, was Bildungsforscher als bedeutenden Faktor für die Reproduktion sozialer Ungleichheit identifizieren.","english":"The stratified school system sorts children relatively early according to supposed ability, which education researchers identify as a significant factor in the reproduction of social inequality."},{"german":"Bildungsföderalismus ermöglicht regionale Anpassung, erschwert jedoch bundesweite Vergleichbarkeit und Mobilität.","english":"Educational federalism enables regional adaptation but makes nationwide comparability and mobility more difficult."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the German education system, PISA, and education policy at B2."}}',
'{"items":[{"word":"gegliedert","translation":"stratified/structured","pronunciation":"geh-GLEE-dert","example":"Gegliedertes Schulsystem."},{"word":"vermeintlich","translation":"supposed/alleged","pronunciation":"fer-MYNT-likh","example":"Vermeintliche Leistungsfähigkeit."},{"word":"identifizieren als","translation":"to identify as","pronunciation":"i-den-ti-fi-TSEER-en als","example":"Als Faktor identifizieren."},{"word":"erschweren","translation":"to make more difficult","pronunciation":"er-SHVER-en","example":"Mobilität erschweren."},{"word":"die Vergleichbarkeit","translation":"comparability","pronunciation":"dee fer-GLYKH-bahr-kyt","example":"Bundesweite Vergleichbarkeit."},{"word":"die Mobilität","translation":"mobility","pronunciation":"dee mo-bi-li-TÄT","example":"Bildungsmobilität."}]}',
'{"title":"Identifizieren als — to identify as (classify, name as)","pattern":"etwas/jemanden als X identifizieren = to identify something/someone as X","explanation":"Identifizieren als = to identify as (classify, recognise as belonging to a category). Forscher identifizieren das als bedeutenden Faktor = Researchers identify this as a significant factor. Can be passive: wird als Faktor identifiziert = is identified as a factor. Also reflexive: sich identifizieren mit = to identify oneself with. Perfect: hat identifiziert. Compare: bezeichnen als (to describe/label as — more linguistic), einordnen als (to classify as), erkennen als (to recognise as).","examples":[{"sentence":"Die Studie identifiziert drei Hauptursachen für das Scheitern.","translation":"The study identifies three main causes of failure."},{"sentence":"Der Täter konnte als Mitarbeiter identifiziert werden.","translation":"The perpetrator could be identified as an employee."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Vermeintlich'' means?","options":["supposed/alleged","apparent","assumed","perceived"],"correctAnswer":"supposed/alleged"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The stratified school system sorts children relatively early according to supposed ability, which education researchers identify as a significant factor in the reproduction of social inequality.","options":["Das gegliederte Schulsystem sortiert Kinder relativ früh nach vermeintlicher Leistungsfähigkeit, was Bildungsforscher als bedeutenden Faktor für die Reproduktion sozialer Ungleichheit identifizieren.","Das Schulsystem benachteiligt Kinder aus sozial schwachen Familien.","Frühes Aussortieren ist ein Problem des deutschen Schulsystems.","Bildungsforscher kritisieren das gegliederte Schulsystem."],"correctAnswer":"Das gegliederte Schulsystem sortiert Kinder relativ früh nach vermeintlicher Leistungsfähigkeit, was Bildungsforscher als bedeutenden Faktor für die Reproduktion sozialer Ungleichheit identifizieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Studie identifiziert drei Hauptursachen für das ___.","options":["Scheitern","Versagen","Misslingen","Fehlschlagen"],"correctAnswer":"Scheitern"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The perpetrator could be identified as an employee","wordBankItems":["Der","Täter","konnte","als","Mitarbeiter","identifiziert","werden","."],"correctAnswer":"Der Täter konnte als Mitarbeiter identifiziert werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erschweren'' means?","options":["to make more difficult","to complicate","to hinder","to obstruct"],"correctAnswer":"to make more difficult"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000020a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss higher education at B2","Use Hochschule vocabulary","Talk about university and academic life"],"explanation":{"intro":"Higher education vocabulary covers university types, Bologna process, and academic culture at B2.","culturalNote":"Germany has ~430 Hochschulen: Universitäten, Fachhochschulen (FH — universities of applied sciences), Kunsthochschulen (arts). Studiengebühren (tuition fees) abolished in most states. Bologna-Prozess (1999) introduced Bachelor/Master/PhD system. Key features: Semesterticket, Studentenwerk (student services), Studentenverbindungen (fraternities), NC (Numerus Clausus — restricted entry for popular subjects like medicine). BAföG = federal student financial aid."},"examples":[{"german":"Der Bologna-Prozess hat das europäische Hochschulsystem harmonisiert, jedoch auch Kritik an der Verschulung des Studiums und der Reduzierung wissenschaftlicher Bildung auf Employability hervorgerufen.","english":"The Bologna process has harmonised the European higher education system, but has also provoked criticism of the schoolification of studies and the reduction of academic education to employability."},{"german":"Die Exzellenzinitiative fördert Spitzenforschung an ausgewählten deutschen Universitäten, was Fragen der Ressourcenverteilung innerhalb des Hochschulsystems aufwirft.","english":"The Excellence Initiative promotes top-level research at selected German universities, which raises questions about the distribution of resources within the higher education system."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss higher education, the Bologna process, and university life at B2."}}',
'{"items":[{"word":"harmonisieren","translation":"to harmonise","pronunciation":"har-mo-ni-ZEER-en","example":"Das System harmonisieren."},{"word":"hervorrufen","translation":"to provoke/cause","pronunciation":"her-FOR-roo-fen","example":"Kritik hervorrufen."},{"word":"die Verschulung","translation":"schoolification","pronunciation":"dee fer-SHOO-loong","example":"Verschulung des Studiums."},{"word":"aufwerfen","translation":"to raise (a question)","pronunciation":"OWF-ver-fen","example":"Fragen aufwerfen."},{"word":"ausgewählt","translation":"selected/chosen","pronunciation":"OWS-geh-vält","example":"Ausgewählte Universitäten."},{"word":"die Ressourcenverteilung","translation":"distribution of resources","pronunciation":"dee reh-SOOR-sen-fer-ty-loong","example":"Ressourcenverteilung."}]}',
'{"title":"Hervorrufen — to provoke, cause, bring about (separable)","pattern":"etwas ruft etwas hervor = something provokes/causes something (separable — for unintended effects/reactions)","explanation":"Hervorrufen (separable) = to provoke, cause, bring about (often unintended effects, reactions, emotions). Der Bologna-Prozess hat Kritik hervorgerufen = The Bologna process has provoked criticism. Present: ruft hervor. Perfect: hat hervorgerufen. Common for emotions (Begeisterung hervorrufen = to arouse enthusiasm) and reactions (Widerstand hervorrufen = to provoke resistance). Compare: verursachen (to cause — neutral, for problems), auslösen (to trigger — for events/reactions), bewirken (to bring about/cause — for intended results).","examples":[{"sentence":"Die Nachricht rief große Bestürzung hervor.","translation":"The news provoked great dismay."},{"sentence":"Die Maßnahmen haben unbeabsichtigte Nebenwirkungen hervorgerufen.","translation":"The measures have caused unintended side effects."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Verschulung'' means?","options":["schoolification","over-structuring","formalisation","rigidification"],"correctAnswer":"schoolification"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Bologna process has harmonised the European higher education system, but has also provoked criticism of the schoolification of studies and the reduction of academic education to employability.","options":["Der Bologna-Prozess hat das europäische Hochschulsystem harmonisiert, jedoch auch Kritik an der Verschulung des Studiums und der Reduzierung wissenschaftlicher Bildung auf Employability hervorgerufen.","Bologna hat das Studium reformiert, aber auch Kritik ausgelöst.","Das Studium wurde durch Bologna vereinheitlicht und verschult.","Employability als Ziel des Studiums ist umstritten."],"correctAnswer":"Der Bologna-Prozess hat das europäische Hochschulsystem harmonisiert, jedoch auch Kritik an der Verschulung des Studiums und der Reduzierung wissenschaftlicher Bildung auf Employability hervorgerufen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Nachricht rief große Bestürzung ___.","options":["hervor","auf","aus","heraus"],"correctAnswer":"hervor"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The measures have caused unintended side effects","wordBankItems":["Die","Maßnahmen","haben","unbeabsichtigte","Nebenwirkungen","hervorgerufen","."],"correctAnswer":"Die Maßnahmen haben unbeabsichtigte Nebenwirkungen hervorgerufen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Aufwerfen'' means?","options":["to raise (a question)","to pose","to throw up","to bring up"],"correctAnswer":"to raise (a question)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000020b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss educational opportunity at B2","Use Bildungschancen vocabulary","Talk about education equality"],"explanation":{"intro":"Educational opportunity vocabulary covers unequal access to education, social mobility, and policy solutions at B2.","culturalNote":"Germany has one of the strongest correlations between parental education/income and children''s educational outcomes in the OECD. Key issues: Bildungsarmut (educational poverty), Chancenungleichheit (inequality of opportunity), Migrationshintergrund (migration background) as a disadvantage factor, Schulsozialarbeit (school social work). Policies: Chancengleichheit, Bildungsgutscheine (education vouchers debate), Vorschulförderung (early childhood education — proven highly effective)."},"examples":[{"german":"Chancengleichheit im Bildungssystem bleibt ein uneingelöstes Versprechen, solange der Bildungserfolg eines Kindes stärker vom sozialen Hintergrund der Eltern als von seinen eigenen Fähigkeiten abhängt.","english":"Equal opportunity in the education system remains an unredeemed promise as long as a child''s educational success depends more on the social background of the parents than on its own abilities."},{"german":"Frühkindliche Bildungsförderung gilt als der kosteneffektivste Ansatz, Bildungsungleichheiten nachhaltig zu verringern.","english":"Early childhood educational support is regarded as the most cost-effective approach to sustainably reducing educational inequalities."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss educational opportunity, inequality, and early education policy at B2."}}',
'{"items":[{"word":"uneingelöst","translation":"unredeemed/unfulfilled","pronunciation":"OON-yn-geh-lörst","example":"Uneingelöstes Versprechen."},{"word":"solange","translation":"as long as","pronunciation":"zo-LAN-geh","example":"Solange der Erfolg abhängt."},{"word":"abhängen von","translation":"to depend on","pronunciation":"AP-heng-en fon","example":"Von Faktoren abhängen."},{"word":"kosteneffektiv","translation":"cost-effective","pronunciation":"KOS-ten-eh-fek-teef","example":"Kosteneffektiver Ansatz."},{"word":"verringern","translation":"to reduce/diminish","pronunciation":"fer-RING-ern","example":"Ungleichheiten verringern."},{"word":"frühkindlich","translation":"early childhood","pronunciation":"FRÜ-kind-likh","example":"Frühkindliche Bildung."}]}',
'{"title":"Solange — as long as (conditional duration)","pattern":"solange + V-final = as long as (the action in the main clause applies for the duration that the condition holds)","explanation":"Solange + V-final = as long as. Chancengleichheit bleibt ein Versprechen, solange der Erfolg vom Hintergrund abhängt = Equal opportunity remains a promise as long as success depends on background. Solange signals that the main clause is conditional on the duration of the subordinate clause state. Compare: während (while — simultaneous, not conditional), bis (until — end-point), wenn (if/when — single event), sofern (provided that/if — more formal conditional).","examples":[{"sentence":"Solange keine Einigung erzielt wird, bleibt die Situation angespannt.","translation":"As long as no agreement is reached, the situation remains tense."},{"sentence":"Das System funktioniert, solange alle Parteien kooperieren.","translation":"The system works as long as all parties cooperate."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Uneingelöst'' means?","options":["unredeemed/unfulfilled","unpaid","broken","unkept"],"correctAnswer":"unredeemed/unfulfilled"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Equal opportunity in the education system remains an unredeemed promise as long as a child''s educational success depends more on the social background of the parents than on its own abilities.","options":["Chancengleichheit im Bildungssystem bleibt ein uneingelöstes Versprechen, solange der Bildungserfolg eines Kindes stärker vom sozialen Hintergrund der Eltern als von seinen eigenen Fähigkeiten abhängt.","Kinder aus armen Familien haben weniger Chancen.","Bildungserfolg hängt in Deutschland stark von der Herkunft ab.","Solange die Herkunft entscheidet, gibt es keine Chancengleichheit."],"correctAnswer":"Chancengleichheit im Bildungssystem bleibt ein uneingelöstes Versprechen, solange der Bildungserfolg eines Kindes stärker vom sozialen Hintergrund der Eltern als von seinen eigenen Fähigkeiten abhängt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Solange keine Einigung erzielt wird, bleibt die Situation ___.","options":["angespannt","schwierig","kritisch","problematisch"],"correctAnswer":"angespannt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The system works as long as all parties cooperate","wordBankItems":["Das","System","funktioniert",",","solange","alle","Parteien","kooperieren","."],"correctAnswer":"Das System funktioniert , solange alle Parteien kooperieren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verringern'' means?","options":["to reduce/diminish","to decrease","to lessen","to lower"],"correctAnswer":"to reduce/diminish"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000020c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital education at B2","Use digitale Bildung vocabulary","Talk about EdTech and digital skills"],"explanation":{"intro":"Digital education vocabulary covers digital learning tools, media literacy, and digital competencies at B2.","culturalNote":"Germany has been criticised for slow digitalisation of schools (Digitalpaket — €5bn federal programme launched 2019, rollout slow). Key terms: Medienkompetenz (media literacy), digitale Kompetenzen (digital skills), BYOD (Bring Your Own Device), Lernmanagement-System (LMS), Blended Learning, Distanzunterricht (distance learning — became critical during COVID). Key challenge: teacher training in digital tools. PISA 2022 Germany results declined, partly linked to digital literacy gaps."},"examples":[{"german":"Medienkompetenz umfasst nicht nur technische Bedienungsfähigkeiten, sondern auch die kritische Bewertung digitaler Informationen und das Verständnis algorithmischer Mechanismen.","english":"Media literacy encompasses not only technical operating skills, but also the critical evaluation of digital information and understanding of algorithmic mechanisms."},{"german":"Digitale Bildung steht vor der Herausforderung, einerseits technologische Teilhabe zu ermöglichen und andererseits kritische Distanz gegenüber digitalen Medien zu fördern.","english":"Digital education faces the challenge of, on the one hand, enabling technological participation and, on the other, promoting a critical distance towards digital media."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital education, media literacy, and digital skills at B2."}}',
'{"items":[{"word":"umfassen","translation":"to encompass","pronunciation":"oom-FAS-en","example":"Medienkompetenz umfasst."},{"word":"die Bedienungsfähigkeit","translation":"operating skill","pronunciation":"dee beh-DEE-noonks-fä-ikh-kyt","example":"Technische Bedienungsfähigkeiten."},{"word":"algorithmisch","translation":"algorithmic","pronunciation":"al-go-RITH-mish","example":"Algorithmische Mechanismen."},{"word":"einerseits ... andererseits","translation":"on the one hand ... on the other","pronunciation":"EY-ner-zyts ... AN-der-er-zyts","example":"Einerseits... andererseits."},{"word":"die Distanz","translation":"distance","pronunciation":"dee dis-TANTS","example":"Kritische Distanz."},{"word":"gegenüber","translation":"towards/vis-à-vis","pronunciation":"GAY-gen-ü-ber","example":"Gegenüber Medien."}]}',
'{"title":"Einerseits ... andererseits — on the one hand ... on the other","pattern":"einerseits X, andererseits Y = on the one hand X, on the other hand Y (balanced contrast)","explanation":"Einerseits...andererseits = on the one hand...on the other hand (balanced, two-sided contrast). Digitale Bildung steht vor der Herausforderung, einerseits Teilhabe zu ermöglichen und andererseits kritische Distanz zu fördern = Digital education faces the challenge of, on the one hand, enabling participation and, on the other, promoting critical distance. Both aspects are presented as valid and not contradictory, unlike sondern (which corrects). Compare: zum einen ... zum anderen (on the one hand ... on the other — same meaning, slightly less formal).","examples":[{"sentence":"Einerseits schafft die Globalisierung neue Chancen, andererseits verstärkt sie Ungleichheiten.","translation":"On the one hand, globalisation creates new opportunities; on the other, it intensifies inequalities."},{"sentence":"Das Projekt war einerseits teuer, andererseits sehr wirkungsvoll.","translation":"The project was, on the one hand, expensive; on the other, very effective."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Algorithmisch'' means?","options":["algorithmic","automated","systematic","computational"],"correctAnswer":"algorithmic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Media literacy encompasses not only technical operating skills, but also the critical evaluation of digital information and understanding of algorithmic mechanisms.","options":["Medienkompetenz umfasst nicht nur technische Bedienungsfähigkeiten, sondern auch die kritische Bewertung digitaler Informationen und das Verständnis algorithmischer Mechanismen.","Medienkompetenz ist mehr als Technik.","Kritisches Denken ist Teil der Medienkompetenz.","Digitale Kompetenz umfasst technische und kritische Fähigkeiten."],"correctAnswer":"Medienkompetenz umfasst nicht nur technische Bedienungsfähigkeiten, sondern auch die kritische Bewertung digitaler Informationen und das Verständnis algorithmischer Mechanismen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Einerseits schafft die Globalisierung neue Chancen, andererseits verstärkt sie ___.","options":["Ungleichheiten","Unterschiede","Disparitäten","Probleme"],"correctAnswer":"Ungleichheiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The project was on the one hand expensive on the other very effective","wordBankItems":["Das","Projekt","war","einerseits","teuer",",","andererseits","sehr","wirkungsvoll","."],"correctAnswer":"Das Projekt war einerseits teuer , andererseits sehr wirkungsvoll ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Distanz'' means?","options":["distance","detachment","space","gap"],"correctAnswer":"distance"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000020d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss vocational training at B2","Use Berufsbildung vocabulary","Talk about the dual system"],"explanation":{"intro":"Vocational training vocabulary covers the German dual system, apprenticeship, and skills shortages at B2.","culturalNote":"Das duale Ausbildungssystem (dual system) = unique German model: Azubi (Auszubildender — apprentice) spends 3-4 days/week at a company (Betrieb) and 1-2 days at a Berufsschule (vocational school). ~320 recognised Ausbildungsberufe (training occupations). ~500,000 apprenticeships per year. Praised internationally: low youth unemployment. Key issue: Fachkräftemangel (skilled worker shortage). IHK (Industrie- und Handelskammer — Chamber of Commerce) and HWK (Handwerkskammer) oversee training."},"examples":[{"german":"Das duale Ausbildungssystem verbindet betriebliche Praxis und schulische Theorie, was eine enge Verzahnung von Lernen und Arbeiten gewährleistet.","english":"The dual training system combines company-based practice and school-based theory, which ensures a close interlinking of learning and working."},{"german":"Angesichts des Fachkräftemangels wird die Aufwertung beruflicher Bildung als gleichwertig zur akademischen Bildung immer dringlicher.","english":"In view of the shortage of skilled workers, upgrading vocational education to be on a par with academic education is becoming increasingly urgent."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss vocational training, the dual system, and skills shortages at B2."}}',
'{"items":[{"word":"die Verzahnung","translation":"interlinking/meshing","pronunciation":"dee fer-TSAH-noong","example":"Enge Verzahnung."},{"word":"gewährleisten","translation":"to ensure/guarantee","pronunciation":"geh-VÄR-lys-ten","example":"Qualität gewährleisten."},{"word":"angesichts","translation":"in view of/given","pronunciation":"AN-geh-zikhts","example":"Angesichts des Mangels."},{"word":"die Aufwertung","translation":"upgrading/revaluation","pronunciation":"dee OWF-ver-toong","example":"Aufwertung der Berufsbildung."},{"word":"gleichwertig","translation":"on a par/of equal value","pronunciation":"GLYKH-ver-tikh","example":"Gleichwertig zur akademischen Bildung."},{"word":"dringlich","translation":"urgent","pronunciation":"DRING-likh","example":"Immer dringlicher."}]}',
'{"title":"Angesichts + genitive — in view of, given (formal concessive/causal)","pattern":"angesichts + genitive = in view of, given, in the face of (formal — introduces a context that makes the main clause warranted)","explanation":"Angesichts + genitive = in view of, given, in the face of (formal preposition). Angesichts des Fachkräftemangels = In view of the shortage of skilled workers. More formal than wegen (because of — genitive/dative, causal) and angesichts implies the situation makes the main clause response appropriate/necessary. Compare: wegen (because of — causal), aufgrund (owing to — similar register), angesichts der Tatsache, dass... (in view of the fact that... — with clause).","examples":[{"sentence":"Angesichts der aktuellen Lage sind Sparmaßnahmen unvermeidlich.","translation":"In view of the current situation, austerity measures are unavoidable."},{"sentence":"Angesichts dieser Ergebnisse müssen wir unsere Strategie überdenken.","translation":"In view of these results, we must reconsider our strategy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gleichwertig'' means?","options":["on a par/of equal value","equivalent","equal","comparable"],"correctAnswer":"on a par/of equal value"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The dual training system combines company-based practice and school-based theory, which ensures a close interlinking of learning and working.","options":["Das duale Ausbildungssystem verbindet betriebliche Praxis und schulische Theorie, was eine enge Verzahnung von Lernen und Arbeiten gewährleistet.","Das duale System kombiniert Schule und Betrieb.","Lernen und Arbeiten werden im dualen System eng verbunden.","Betrieb und Berufsschule ergänzen sich im dualen System."],"correctAnswer":"Das duale Ausbildungssystem verbindet betriebliche Praxis und schulische Theorie, was eine enge Verzahnung von Lernen und Arbeiten gewährleistet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Angesichts der aktuellen Lage sind Sparmaßnahmen ___.","options":["unvermeidlich","notwendig","unausweichlich","erforderlich"],"correctAnswer":"unvermeidlich"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In view of these results we must reconsider our strategy","wordBankItems":["Angesichts","dieser","Ergebnisse","müssen","wir","unsere","Strategie","überdenken","."],"correctAnswer":"Angesichts dieser Ergebnisse müssen wir unsere Strategie überdenken ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gewährleisten'' means?","options":["to ensure/guarantee","to secure","to provide","to safeguard"],"correctAnswer":"to ensure/guarantee"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000020e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss lifelong learning at B2","Use lebenslanges Lernen vocabulary","Talk about continuing education"],"explanation":{"intro":"Lifelong learning vocabulary covers adult education, continuing professional development, and the learning society at B2.","culturalNote":"Lebenslanges Lernen (lifelong learning) is an EU and German policy priority. Key institutions: Volkshochschule (VHS — adult education centres — ~900 in Germany), Fernuniversität Hagen (distance university), betriebliche Weiterbildung (company training). Key EU framework: European Qualifications Framework (EQF). Key drivers: Automatisierung (automation), Digitalisierung, Fachkräftemangel. Bildungsurlaub (paid educational leave — 5 days/year, most German states)."},"examples":[{"german":"In einer sich rasant wandelnden Arbeitswelt wird lebenslanges Lernen nicht mehr als optionale Tugend, sondern als strukturelle Notwendigkeit zur Aufrechterhaltung von Beschäftigungsfähigkeit betrachtet.","english":"In a rapidly changing world of work, lifelong learning is no longer regarded as an optional virtue, but as a structural necessity for maintaining employability."},{"german":"Betriebliche Weiterbildung ist sowohl im Interesse der Unternehmen als auch der Beschäftigten und sollte als gemeinsame Investition betrachtet werden.","english":"Company-based continuing education is both in the interest of enterprises and employees and should be regarded as a shared investment."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss lifelong learning, continuing education, and the learning society at B2."}}',
'{"items":[{"word":"rasant","translation":"rapid/fast","pronunciation":"rah-ZANT","example":"Rasant wandelnd."},{"word":"die Notwendigkeit","translation":"necessity","pronunciation":"dee NOT-ven-dikh-kyt","example":"Strukturelle Notwendigkeit."},{"word":"die Aufrechterhaltung","translation":"maintenance/upholding","pronunciation":"dee OWF-rekht-er-hal-toong","example":"Aufrechterhaltung der Beschäftigungsfähigkeit."},{"word":"die Beschäftigungsfähigkeit","translation":"employability","pronunciation":"dee beh-SHEF-ti-goonks-fä-ikh-kyt","example":"Beschäftigungsfähigkeit erhalten."},{"word":"sowohl ... als auch","translation":"both ... and","pronunciation":"zo-VOL ... als owkh","example":"Sowohl als auch."},{"word":"betrachten als","translation":"to regard as","pronunciation":"beh-TRAKH-ten als","example":"Als Investition betrachten."}]}',
'{"title":"Sowohl ... als auch — both ... and (additive, formal)","pattern":"sowohl X als auch Y = both X and Y (additive — includes both without either/or)","explanation":"Sowohl...als auch = both...and (formal additive). Sowohl im Interesse der Unternehmen als auch der Beschäftigten = both in the interest of companies and employees. Both elements are fully included; there is no exclusion or preference. Compare: nicht nur...sondern auch (not only...but also — similar but stresses surprise of adding Y), weder...noch (neither...nor — exclusion), entweder...oder (either...or — choice). Sowohl...als auch is symmetric and formal.","examples":[{"sentence":"Die Lösung muss sowohl technisch als auch ethisch vertretbar sein.","translation":"The solution must be both technically and ethically defensible."},{"sentence":"Sowohl die Kosten als auch die Zeit wurden unterschätzt.","translation":"Both the costs and the time were underestimated."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Rasant'' means?","options":["rapid/fast","swift","speedy","quick"],"correctAnswer":"rapid/fast"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In a rapidly changing world of work, lifelong learning is no longer regarded as an optional virtue, but as a structural necessity for maintaining employability.","options":["In einer sich rasant wandelnden Arbeitswelt wird lebenslanges Lernen nicht mehr als optionale Tugend, sondern als strukturelle Notwendigkeit zur Aufrechterhaltung von Beschäftigungsfähigkeit betrachtet.","Lebenslanges Lernen ist in der modernen Arbeitswelt unverzichtbar.","Die Digitalisierung macht Weiterbildung notwendig.","Wer sich nicht weiterbildet, verliert seinen Arbeitsplatz."],"correctAnswer":"In einer sich rasant wandelnden Arbeitswelt wird lebenslanges Lernen nicht mehr als optionale Tugend, sondern als strukturelle Notwendigkeit zur Aufrechterhaltung von Beschäftigungsfähigkeit betrachtet."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Lösung muss sowohl technisch als auch ethisch ___ sein.","options":["vertretbar","akzeptabel","machbar","durchführbar"],"correctAnswer":"vertretbar"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Both the costs and the time were underestimated","wordBankItems":["Sowohl","die","Kosten","als","auch","die","Zeit","wurden","unterschätzt","."],"correctAnswer":"Sowohl die Kosten als auch die Zeit wurden unterschätzt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Betrachten als'' means?","options":["to regard as","to see as","to consider as","to view as"],"correctAnswer":"to regard as"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000020f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss science and research at B2","Use Wissenschaft vocabulary","Talk about the research landscape"],"explanation":{"intro":"Science and research vocabulary covers the research system, funding, and academic careers at B2.","culturalNote":"Germany is a leading research nation: 4th in R&D spending globally (~3% of GDP). Key institutions: Deutsche Forschungsgemeinschaft (DFG — German Research Foundation), Helmholtz Association (large-scale research), Max-Planck-Gesellschaft (fundamental research), Fraunhofer-Gesellschaft (applied research), Leibniz Association. Nobel laureates: 108 German laureates. Key issues: Drittmittelabhängigkeit (dependence on third-party funding), Nachwuchsförderung (early-career support), Internationalität."},"examples":[{"german":"Grundlagenforschung, die keinen unmittelbaren wirtschaftlichen Nutzen verspricht, ist für langfristigen wissenschaftlichen Fortschritt unerlässlich und verdient staatliche Förderung.","english":"Basic research that promises no immediate economic benefit is indispensable for long-term scientific progress and deserves public support."},{"german":"Die zunehmende Drittmittelabhängigkeit an deutschen Hochschulen befördert kurzfristiges, anwendungsorientiertes Denken auf Kosten frei gewählter Forschungsthemen.","english":"The increasing dependence on third-party funding at German universities promotes short-term, application-oriented thinking at the expense of freely chosen research topics."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the research system, funding, and academic careers at B2."}}',
'{"items":[{"word":"unerlässlich","translation":"indispensable","pronunciation":"OON-er-les-likh","example":"Unerlässlich für Fortschritt."},{"word":"unmittelbar","translation":"immediate/direct","pronunciation":"OON-mi-tel-bahr","example":"Unmittelbarer Nutzen."},{"word":"versprechen","translation":"to promise","pronunciation":"fer-SHPREKH-en","example":"Nutzen versprechen."},{"word":"befördern","translation":"to promote/advance","pronunciation":"beh-FÖR-dern","example":"Kurzfristiges Denken befördern."},{"word":"auf Kosten","translation":"at the expense of","pronunciation":"owf KOS-ten","example":"Auf Kosten von."},{"word":"die Grundlagenforschung","translation":"basic research","pronunciation":"dee GROOND-lah-gen-for-shoong","example":"Grundlagenforschung fördern."}]}',
'{"title":"Auf Kosten + genitive — at the expense of","pattern":"auf Kosten + genitive = at the expense of (the genitive noun suffers the cost)","explanation":"Auf Kosten + genitive = at the expense of. Kurzfristiges Denken auf Kosten frei gewählter Forschungsthemen = Short-term thinking at the expense of freely chosen research topics. Idiomatic phrase: X happens/grows, but Y bears the cost. Common in political and economic discourse. Compare: zulasten (to the detriment of — similar), zum Nachteil (to the disadvantage of — more direct), auf Kosten der Gesundheit (at the expense of health).","examples":[{"sentence":"Das Wachstum erfolgte auf Kosten der Umwelt.","translation":"The growth occurred at the expense of the environment."},{"sentence":"Er verfolgte seine Karriere auf Kosten seiner Familie.","translation":"He pursued his career at the expense of his family."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unerlässlich'' means?","options":["indispensable","essential","necessary","vital"],"correctAnswer":"indispensable"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Basic research that promises no immediate economic benefit is indispensable for long-term scientific progress and deserves public support.","options":["Grundlagenforschung, die keinen unmittelbaren wirtschaftlichen Nutzen verspricht, ist für langfristigen wissenschaftlichen Fortschritt unerlässlich und verdient staatliche Förderung.","Grundlagenforschung hat keinen sofortigen Nutzen, ist aber wichtig.","Wissenschaftlicher Fortschritt braucht Grundlagenforschung.","Grundlagenforschung sollte staatlich gefördert werden."],"correctAnswer":"Grundlagenforschung, die keinen unmittelbaren wirtschaftlichen Nutzen verspricht, ist für langfristigen wissenschaftlichen Fortschritt unerlässlich und verdient staatliche Förderung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Wachstum erfolgte auf Kosten der ___.","options":["Umwelt","Natur","Ökologie","Biosphäre"],"correctAnswer":"Umwelt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He pursued his career at the expense of his family","wordBankItems":["Er","verfolgte","seine","Karriere","auf","Kosten","seiner","Familie","."],"correctAnswer":"Er verfolgte seine Karriere auf Kosten seiner Familie ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unmittelbar'' means?","options":["immediate/direct","proximate","direct","instant"],"correctAnswer":"immediate/direct"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000210',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss research ethics at B2","Use Forschungsethik vocabulary","Talk about ethical principles in science"],"explanation":{"intro":"Research ethics vocabulary covers ethical principles, research integrity, and the governance of science at B2.","culturalNote":"Research ethics in Germany: Deutsche Forschungsgemeinschaft (DFG) Leitlinien zur Sicherung guter wissenschaftlicher Praxis (2019 — 19 guidelines). Key issues: Datenfälschung (data fabrication), Plagiat, Doppelveröffentlichung (duplicate publication), Interessenkonflikt (conflict of interest). Committees: Ombudspersonen für die Wissenschaft (ombudspersons for science). High-profile cases: Guttenberg (PhD thesis plagiarism 2011), Schavan (Education Minister resigned 2013). Bioethik (bioethics) controversy: embryo research, CRISPR."},"examples":[{"german":"Gute wissenschaftliche Praxis beruht auf den Grundsätzen der Ehrlichkeit, Sorgfalt und Transparenz und schließt die Dokumentation, Archivierung und Zugänglichmachung von Primärdaten ein.","english":"Good scientific practice is based on the principles of honesty, care, and transparency and includes the documentation, archiving, and making accessible of primary data."},{"german":"Interessenkonflikte in der Forschung müssen offengelegt werden, da sie die Objektivität wissenschaftlicher Befunde und die öffentliche Wahrnehmung der Wissenschaft untergraben können.","english":"Conflicts of interest in research must be disclosed, since they can undermine the objectivity of scientific findings and the public perception of science."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss research ethics, scientific integrity, and conflicts of interest at B2."}}',
'{"items":[{"word":"beruhen auf","translation":"to be based on","pronunciation":"beh-ROO-en owf","example":"Auf Grundsätzen beruhen."},{"word":"die Sorgfalt","translation":"care/diligence","pronunciation":"dee ZOR-gfalt","example":"Wissenschaftliche Sorgfalt."},{"word":"zugänglich machen","translation":"to make accessible","pronunciation":"TSOO-geng-likh MAKHen","example":"Daten zugänglich machen."},{"word":"offenlegen","translation":"to disclose","pronunciation":"OF-en-lay-gen","example":"Interessenkonflikte offenlegen."},{"word":"der Befund","translation":"finding","pronunciation":"dayr beh-FOOND","example":"Wissenschaftliche Befunde."},{"word":"die Wahrnehmung","translation":"perception","pronunciation":"dee VAHR-nay-moong","example":"Öffentliche Wahrnehmung."}]}',
'{"title":"Beruhen auf — to be based on, to rest on","pattern":"etwas beruht auf + dative = something is based on, rests on (the dative noun is the foundation)","explanation":"Beruhen auf + dative = to be based on, to rest on. Gute Praxis beruht auf Ehrlichkeit = Good practice is based on honesty. The dative noun is the foundation. Perfect: hat beruht. Note: beruhen is an intransitive verb — something rests on something else; it cannot have an accusative object. Compare: basieren auf (to be based on — same meaning, slightly more modern/colloquial), gründen auf (to be founded on — also used), fußen auf (to rest on — more literary).","examples":[{"sentence":"Das Vertrauen beruht auf jahrelanger Zusammenarbeit.","translation":"The trust is based on years of collaboration."},{"sentence":"Die Entscheidung beruhte auf unvollständigen Informationen.","translation":"The decision was based on incomplete information."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Sorgfalt'' means?","options":["care/diligence","thoroughness","accuracy","precision"],"correctAnswer":"care/diligence"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Good scientific practice is based on the principles of honesty, care, and transparency and includes the documentation, archiving, and making accessible of primary data.","options":["Gute wissenschaftliche Praxis beruht auf den Grundsätzen der Ehrlichkeit, Sorgfalt und Transparenz und schließt die Dokumentation, Archivierung und Zugänglichmachung von Primärdaten ein.","Wissenschaftliche Integrität erfordert Ehrlichkeit und Transparenz.","Gute Forschungspraxis beinhaltet Dokumentation und Datentransparenz.","Wissenschaft muss ehrlich, sorgfältig und transparent sein."],"correctAnswer":"Gute wissenschaftliche Praxis beruht auf den Grundsätzen der Ehrlichkeit, Sorgfalt und Transparenz und schließt die Dokumentation, Archivierung und Zugänglichmachung von Primärdaten ein."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Vertrauen beruht auf jahrelanger ___.","options":["Zusammenarbeit","Kooperation","Partnerschaft","Kollaboration"],"correctAnswer":"Zusammenarbeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The decision was based on incomplete information","wordBankItems":["Die","Entscheidung","beruhte","auf","unvollständigen","Informationen","."],"correctAnswer":"Die Entscheidung beruhte auf unvollständigen Informationen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Offenlegen'' means?","options":["to disclose","to reveal","to expose","to publish"],"correctAnswer":"to disclose"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000211',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss science communication at B2","Use Wissenschaftskommunikation vocabulary","Talk about public understanding of science"],"explanation":{"intro":"Science communication vocabulary covers science journalism, public understanding, and citizen science at B2.","culturalNote":"Wissenschaftskommunikation (science communication) has grown in importance in Germany. Key platforms: Spektrum der Wissenschaft (Scientific American Germany), MaxWissen, Science Slam (science slams — popular in Germany). Key issues: Wissenschaftsskepsis (science scepticism), COVID-19 Impfskepsis, Fake Science (fraudulent journals), Open Access debate. Key bodies: Wissenschaft im Dialog (WiD — science communication organisation), Deutsches Wissenschafts-PR-Büro."},"examples":[{"german":"Wissenschaftskommunikation hat die Aufgabe, komplexe Erkenntnisse verständlich und nuanciert zu vermitteln, ohne sie so weit zu vereinfachen, dass sie inhaltlich entstellt werden.","english":"Science communication has the task of conveying complex findings in an understandable and nuanced way, without simplifying them to the point that they are distorted in content."},{"german":"Das Vertrauen der Öffentlichkeit in die Wissenschaft hängt maßgeblich davon ab, dass Forscher offen über Unsicherheiten und die Grenzen ihrer Erkenntnisse kommunizieren.","english":"The trust of the public in science depends substantially on researchers communicating openly about uncertainties and the limits of their findings."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss science communication, public trust in science, and science journalism at B2."}}',
'{"items":[{"word":"die Erkenntnis","translation":"finding/insight","pronunciation":"dee er-KENT-nis","example":"Wissenschaftliche Erkenntnisse."},{"word":"entstellen","translation":"to distort","pronunciation":"ent-SHTEL-en","example":"Inhaltlich entstellen."},{"word":"maßgeblich","translation":"substantially/decisively","pronunciation":"MAHS-gayp-likh","example":"Maßgeblich davon abhängen."},{"word":"die Unsicherheit","translation":"uncertainty","pronunciation":"dee OON-zi-kher-hyt","example":"Über Unsicherheiten kommunizieren."},{"word":"nuanciert","translation":"nuanced","pronunciation":"noo-an-TSEERT","example":"Nuanciert vermitteln."},{"word":"vereinfachen","translation":"to simplify","pronunciation":"fer-YN-fakh-en","example":"Nicht zu sehr vereinfachen."}]}',
'{"title":"Ohne sie so weit zu...dass — without...to the point that","pattern":"ohne X so weit zu..., dass = without doing X to the extent that (non-finite same-subject + result clause)","explanation":"Ohne...so weit...dass = without...to the extent that (combines ohne + zu with a result clause). Vereinfachen ohne sie so weit zu vereinfachen, dass sie entstellt werden = simplify without simplifying them to the point that they are distorted. Structure: ohne [object] so weit zu [Verb], dass [result clause with V-final]. The ohne signals the boundary that should not be crossed; so weit...dass describes what would happen if it were crossed. This is a B2 construction for expressing limits and thresholds.","examples":[{"sentence":"Man kann kritisch sein, ohne so weit zu gehen, dass man konstruktiv wird.","translation":"One can be critical without going so far that one becomes unconstructive."},{"sentence":"Wir müssen kürzen, ohne so weit zu kürzen, dass die Qualität leidet.","translation":"We must cut costs without cutting so far that quality suffers."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Maßgeblich'' means?","options":["substantially/decisively","significantly","importantly","critically"],"correctAnswer":"substantially/decisively"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Science communication has the task of conveying complex findings in an understandable and nuanced way, without simplifying them to the point that they are distorted in content.","options":["Wissenschaftskommunikation hat die Aufgabe, komplexe Erkenntnisse verständlich und nuanciert zu vermitteln, ohne sie so weit zu vereinfachen, dass sie inhaltlich entstellt werden.","Wissenschaft muss verständlich kommuniziert werden.","Science Communication muss einfach sein, ohne Genauigkeit zu verlieren.","Komplexe Erkenntnisse müssen vereinfacht, aber nicht verfälscht werden."],"correctAnswer":"Wissenschaftskommunikation hat die Aufgabe, komplexe Erkenntnisse verständlich und nuanciert zu vermitteln, ohne sie so weit zu vereinfachen, dass sie inhaltlich entstellt werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wir müssen kürzen, ohne so weit zu kürzen, dass die Qualität ___.","options":["leidet","schadet","verschlechtert","sinkt"],"correctAnswer":"leidet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: One can be critical without going so far that one becomes unconstructive","wordBankItems":["Man","kann","kritisch","sein",",","ohne","so","weit","zu","gehen",",","dass","man","konstruktiv","wird","."],"correctAnswer":"Man kann kritisch sein , ohne so weit zu gehen , dass man konstruktiv wird ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Entstellen'' means?","options":["to distort","to disfigure","to misrepresent","to corrupt"],"correctAnswer":"to distort"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000212',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss peer review at B2","Use Publikation vocabulary","Talk about academic publishing"],"explanation":{"intro":"Peer review and publication vocabulary covers academic publishing, open access, and research evaluation at B2.","culturalNote":"Peer Review (Begutachtungsverfahren): standard method of quality control in academic publishing. Key journals: Springer, Wiley, Elsevier dominant. Open-Access-Bewegung: Germany signed the Berlin Declaration on Open Access (2003). DEAL-Vertrag (2019 — transformative agreement between German universities and Wiley for open access). Predatory journals (Raubjournale) problem. Impact Factor, h-Index used in evaluation. Key critique: publish or perish culture (Veröffentlichungskultur)."},"examples":[{"german":"Das Peer-Review-Verfahren dient der Qualitätssicherung wissenschaftlicher Publikationen, ist jedoch nicht frei von Verzerrungen durch persönliche Bekanntschaften oder ideologische Präferenzen.","english":"The peer review procedure serves to quality-assure scientific publications, but is not free from distortions through personal acquaintances or ideological preferences."},{"german":"Open Access ermöglicht den freien Zugang zu wissenschaftlichen Ergebnissen und demokratisiert den Wissenszugang, sofern die Finanzierungsmodelle nachhaltig gestaltet werden.","english":"Open access enables free access to scientific results and democratises access to knowledge, provided that the financing models are designed sustainably."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss peer review, academic publishing, and open access at B2."}}',
'{"items":[{"word":"die Qualitätssicherung","translation":"quality assurance","pronunciation":"dee kvah-li-TÄTS-zi-kher-oong","example":"Qualitätssicherung."},{"word":"die Verzerrung","translation":"distortion/bias","pronunciation":"dee fer-TSER-oong","example":"Verzerrungen vermeiden."},{"word":"die Bekanntschaft","translation":"acquaintance","pronunciation":"dee beh-KANT-shaft","example":"Persönliche Bekanntschaften."},{"word":"sofern","translation":"provided that/if","pronunciation":"zo-FERN","example":"Sofern Bedingungen erfüllt sind."},{"word":"gestalten","translation":"to design/shape","pronunciation":"geh-SHTAL-ten","example":"Nachhaltig gestalten."},{"word":"demokratisieren","translation":"to democratise","pronunciation":"deh-mo-krah-ti-ZEER-en","example":"Den Wissenszugang demokratisieren."}]}',
'{"title":"Sofern — provided that, if (conditional — more formal than wenn)","pattern":"sofern + V-final = provided that, if (conditional — condition must be met for main clause to hold)","explanation":"Sofern + V-final = provided that, if (formal conditional — stronger and more formal than wenn for conditions). Open Access demokratisiert Wissenszugang, sofern Finanzierungsmodelle nachhaltig gestaltet werden = Open Access democratises access to knowledge, provided that financing models are designed sustainably. Sofern introduces a condition that must be met; without it, the main clause does not hold. Compare: wenn (if — general conditional), falls (if/in case — less formal than sofern), vorausgesetzt dass (provided that — even more explicit).","examples":[{"sentence":"Sofern alle Unterlagen vollständig eingereicht werden, wird der Antrag bearbeitet.","translation":"Provided that all documents are submitted in full, the application will be processed."},{"sentence":"Das Projekt kann starten, sofern die Finanzierung gesichert ist.","translation":"The project can start, provided that the financing is secured."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Verzerrung'' means?","options":["distortion/bias","deviation","error","skew"],"correctAnswer":"distortion/bias"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The peer review procedure serves to quality-assure scientific publications, but is not free from distortions through personal acquaintances or ideological preferences.","options":["Das Peer-Review-Verfahren dient der Qualitätssicherung wissenschaftlicher Publikationen, ist jedoch nicht frei von Verzerrungen durch persönliche Bekanntschaften oder ideologische Präferenzen.","Peer Review sichert die Qualität wissenschaftlicher Arbeiten.","Peer Review ist wichtig, hat aber auch Nachteile.","Verzerrungen durch persönliche Beziehungen sind im Peer Review möglich."],"correctAnswer":"Das Peer-Review-Verfahren dient der Qualitätssicherung wissenschaftlicher Publikationen, ist jedoch nicht frei von Verzerrungen durch persönliche Bekanntschaften oder ideologische Präferenzen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt kann starten, sofern die Finanzierung ___ ist.","options":["gesichert","gewährleistet","sichergestellt","garantiert"],"correctAnswer":"gesichert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Provided that all documents are submitted the application will be processed","wordBankItems":["Sofern","alle","Unterlagen","vollständig","eingereicht","werden",",","wird","der","Antrag","bearbeitet","."],"correctAnswer":"Sofern alle Unterlagen vollständig eingereicht werden , wird der Antrag bearbeitet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Sofern'' means?","options":["provided that/if","as long as","given that","only if"],"correctAnswer":"provided that/if"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

